import yaml,glob
rows=[]
for f in sorted(glob.glob('*.yaml')):
    d=yaml.safe_load(open(f))
    if d.get('status')!='open': continue
    body=(d.get('body') or '').strip()
    title=body.split('\n\n')[0].replace('\n',' ')[:150]
    md=d.get('metadata') or {}
    pv=md.get('provenance') or {}
    rows.append((d['kind'], d['id'], d.get('audience'), md.get('owner'), pv.get('task'), d.get('created_at','')[:10], title))
for k in ['protection','conversation','issue','hint','info','memory']:
    print(f'===== {k} =====')
    for r in rows:
        if r[0]==k: print(f'{r[1]} aud={r[2]} own={r[3]} by={r[4]} {r[5]} | {r[6]}')
EOF

